h"]={examples={{body="\n  local fetch = require(\"cosmic.fetch\")\n  local result = fetch.Fetch(\"https://httpbin.org/get\")\n  print(\"status:\", result.status)\n  print(\"ok:\", result.ok)\n  -- Output:\n  -- status:\t200\n  -- ok:\ttrue\n", description=" Example_get demonstrates a simple HTTP GET request", expected_output="status:\t200\n  -- ok:\ttrue\n", line=69, name="Example_get"}, {body="\n  local fetch = require(\"cosmic.fetch\")\n  local json = require(\"cosmic.json\")\n  local result = fetch.Fetch(\"https://httpbin.org/json\")\n  local data = json.decode(result.body) as {string:{string:string}}\n  print(\"title:\", data.slideshow.title)\n  -- Output:\n  -- title:\tSample Slide Show\n", description=" Example_get_json demonstrates fetching and parsing JSON", expected_output="title:\tSample Slide Show\n", line=80, name="Example_get_json"}}, file="lib/cosmic/fetch.tl", functions={{is_local=true, line=24, name="do_fetch", params={}, returns={}, signature="(url: string, opts?: Opts): Result"}, {description=" Fetch a URL and return structured result.", is_local=true, line=47, name="Fetch", params={{description="URL to fetch", name="url", param_type="string"}, {description="optional fetch options (retry, headers, etc.)", name="opts", param_type="Opts"}}, returns={{description="fetch result with ok, status, headers, body, or error", return_type="Result"}}, signature="(url: string, opts?: Opts): Result"}}, module_doc=" Structured HTTP fetch with optional retry.\n Wraps cosmo.Fetch with structured results to prevent accidentally discarding errors.", records={{description=" Result from a fetch operation.", fields={{"ok", "boolean", ""}, {"status", "number", ""}, {"headers", "{string:string}", ""}, {"body", "string", ""}, {"error", "string", ""}}, line=8, name="Result"}, {fields={{"headers", "{string:string}", ""}, {"maxresponse", "number", ""}, {"max_attempts", "number", ""}, {"max_delay", "number", ""}, {"should_retry", "function(Result): boolean", ""}}, line=16, nam