ing uses standard getopt format:\n - A letter means that option takes no argument (e.g., \"h\" for -h)\n - A letter followed by : means it requires an argument (e.g., \"o:\" for -o file)\n - A letter followed by :: means it takes an optional argument (e.g., \"v::\" for -v or -vN)\n Example - Basic usage:\n     local getopt = require(\"cosmic.getopt\")\n     local parser = getopt.new(arg, \"hvo:\", {\n       {name = \"help\",    has_arg = \"none\",     short = \"h\"},\n       {name = \"verbose\", has_arg = \"none\",     short = \"v\"},\n       {name = \"output\",  has_arg = \"required\", short = \"o\"},\n     })\n     local verbose = false\n     local output: string\n     while true do\n       local opt, optarg = parser:next()\n       if not opt then break end\n       -- Both -h and --help return \"h\" since short alias is defined\n       if opt == \"h\" then\n         print(\"Usage: ...\")\n         os.exit(0)\n       elseif opt == \"v\" then\n         verbose = true\n       elseif opt == \"o\" then\n         output = optarg\n       end\n     end\n     local files = parser:remaining()\n     for _, unknown in ipairs(parser:unknown()) do\n       io.stderr:write(\"warning: unknown option: \" .. unknown .. \"\\n\")\n     end", is_local=true, line=79, name="new", params={{description="The argument list to parse (typically the global `arg` table)", name="args", param_type="{string}"}, {description="Short options specification", name="optstring", param_type="string"}, {description="Long options table, each entry is {name, has_arg, short}", name="longopts", param_type="{LongOpt}|nil"}}, returns={{description="A parser instance for iterating through options", return_type="Parser"}}, signature="(args: {string}, optstring: string, longopts?: {LongOpt}): Parser"}}, module_doc=" Command-line option parsing utilities.\n Wraps cosmo.getopt with a convenient Teal-typed interface for parsing\n command-line arguments with support for short options, long options,\n and optional/required arguments.", records={{description=" Defines a long option with its name, argument behavior, and optional short alias.\n @field name string The long option name (e.g., \"help\" for --help)\n @field has_arg string Whether the option takes an argument: \"none\", \"required\", or \"optional\"\n @field short string|nil The equivalent short option character (e.g., \"h\")", fields={{"name", "string", ""}, {"has_arg", "string", ""}, {"short", "string", ""}}, line=11, name="LongOpt"}, {description=" Parser for iterating through command-line options.\n Use next() in a loop to get each option, then remaining() and unknown()\n after parsing is complete.", fields={{"next", "function(self: Parser): string, string", " Get the next option from the parser.\n Returns the short option character when a short alias is defined,\n or the long option name when no short alias exists.\n This means both `-h` and `--help` return `\"h\"` if `short = \"h\"` is set.\n Returns nil when no more options remain.\n If the option is unknown, returns \"?\" as the option name and the\n unknown option string as the argument."}, {"remaining", "function(self: Parser): {string}", " Get remaining non-option arguments after all options have been parsed.\n Call this after the next() loop completes to get positional arguments."}, {"unknown", "function(self: Parser): {string}", " Get any unknown options that were encountered during parsing.\n Useful for error reporting or warning about unrecognized options."}}, line=20, name="Parser"}, {fields={{"LongOpt", "LongOpt", " Type for defining long options"}, {"Parser", "Parser", " Type for the option parser"}, {"new", "function(args: {string}, optstring: string, longopts?: {LongOpt}): Parser", " Create a new option parser"}}, line=107, name="GetoptModule"}}}, ["cosmic.init"]={examples={}, file="lib/cosmic/init.tl", functions={{description=" Run a main function and exit with its return code.\n Calls the provided function only if running as main script.\n Writes erro