{{body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\")\n  db:exec(\"CREATE TABLE kv (k TEXT PRIMARY KEY, v TEXT)\")\n  db:exec(\"INSERT INTO kv (k, v) VALUES ('hello', 'world')\")\n  for row in db:query(\"SELECT * FROM kv\") do\n    print(row.k, row.v)\n  end\n  db:close()\n  -- Output:\n  -- hello\tworld\n", description=" Example_open demonstrates opening an in-memory database", expected_output="hello\tworld\n", line=5, name="Example_open"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\")\n  db:exec(\"CREATE TABLE users (id INTEGER PRIMARY KEY, name TEXT)\")\n\n  local stmt = db:prepare(\"INSERT INTO users (name) VALUES (?)\")\n  stmt:bind(\"Alice\")\n  stmt:exec()\n  stmt:reset()\n  stmt:bind(\"Bob\")\n  stmt:exec()\n  stmt:close()\n\n  for row in db:query(\"SELECT * FROM users ORDER BY id\") do\n    print(row.id, row.name)\n  end\n  db:close()\n  -- Output:\n  -- 1\tAlice\n  -- 2\tBob\n", description=" Example_prepared demonstrates prepared statements", expected_output="1\tAlice\n  -- 2\tBob\n", line=19, name="Example_prepared"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\")\n  db:exec(\"CREATE TABLE nums (n INTEGER)\")\n  for i = 1, 5 do\n    db:exec(\"INSERT INTO nums (n) VALUES (\" .. i .. \")\")\n  end\n\n  for row in db:query(\"SELECT * FROM nums WHERE n > ?\", 2) do\n    print(row.n)\n  end\n  db:close()\n  -- Output:\n  -- 3\n  -- 4\n  -- 5\n", description=" Example_query_params demonstrates query with parameters", expected_output="3\n  -- 4\n  -- 5\n", line=42, name="Example_query_params"}, {body="\n  local sqlite = require(\"cosmic.sqlite\")\n  local db = sqlite.open(\":memory:\")\n  db:exec(\"CREATE TABLE cities (id INTEGER PRIMARY KEY, name TEXT, pop INTEGER)\")\n\n  db:exec(\"INSERT INTO cities (name, pop) VALUES (?, ?)\", \"Tokyo\", 13960000)\n  db:exec(\"INSERT INTO cities (name, pop) VALUES (?, ?)\", \"Delhi\", 16787941