ved: number): boolean", ""}, {"umask", "function(newmask: number): number", ""}, {"chroot", "function(path: string): boolean", ""}}, line=102, name="UserModule"}}}, ["cosmic.walk"]={examples={{body="\n  local walk_m = require(\"cosmic.walk\")\n  local unix_m = require(\"cosmo.unix\")\n  local path_m = require(\"cosmo.path\")\n\n  -- Create temp dir with test files\n  local tmpdir = os.getenv(\"TEST_TMPDIR\") or \"/tmp/walk_example\"\n  unix_m.makedirs(tmpdir)\n  local f1 = io.open(path_m.join(tmpdir, \"a.lua\"), \"w\")\n  if f1 then f1:write(\"-- a\") f1:close() end\n  local f2 = io.open(path_m.join(tmpdir, \"b.lua\"), \"w\")\n  if f2 then f2:write(\"-- b\") f2:close() end\n  local f3 = io.open(path_m.join(tmpdir, \"c.txt\"), \"w\")\n  if f3 then f3:write(\"text\") f3:close() end\n\n  local files = walk_m.collect(tmpdir, \"%.lua$\")\n  table.sort(files)\n  print(\"found\", #files, \"lua files\")\n  for _, file in ipairs(files) do\n    print(path_m.basename(file))\n  end\n\n  unix_m.rmrf(tmpdir)\n  -- Output:\n  -- found\t2\tlua files\n  -- a.lua\n  -- b.lua\n", description=" Example_collect demonstrates collecting files matching a pattern", expected_output="found\t2\tlua files\n  -- a.lua\n  -- b.lua\n", line=114, name="Example_collect"}, {body="\n  local walk_m = require(\"cosmic.walk\")\n  local unix_m = require(\"cosmo.unix\")\n  local path_m = require(\"cosmo.path\")\n\n  -- Create temp dir with test structure\n  local tmpdir = os.getenv(\"TEST_TMPDIR\") or \"/tmp/walk_example2\"\n  unix_m.makedirs(path_m.join(tmpdir, \"sub\"))\n  local f1 = io.open(path_m.join(tmpdir, \"root.txt\"), \"w\")\n  if f1 then f1:write(\"root\") f1:close() end\n  local f2 = io.open(path_m.join(tmpdir, \"sub\", \"child.txt\"), \"w\")\n  if f2 then f2:write(\"child\") f2:close() end\n\n  local count = 0\n  walk_m.walk(tmpdir, function(_: string, _: string, s: any, _: any): boolean\n    local st = s as Stat\n    if not unix_m.S_ISDIR(st:mode()) then\n      count = count + 1\n    end\n    return true\n  end)\n  print(\"visited\", count, \"files\")\n\n  unix_m.rmrf(tmpdir)\n  -- Output:\n  -- visited\t2\tfiles\n", description=" Example_walk demonstrates walking a directory tree with a visitor", expected_output="visited\t2\tfiles\n", line=144, name="Example_walk"}}, file="lib/cosmic/walk.tl", functions={{description=" Walk a directory tree, calling visitor for each entry.\n Recursively traverses subdirectories unless visitor returns false.", is_local=true, line=39, name="walk", params={{description="The directory to walk", name="dir", param_type="string"}, {description="Function called for each file and directory", name="visitor", param_type="Visitor"}, {description="Optional context passed to visitor function", name="ctx", param_type="T"}}, returns={{description="The context object, potentially modified by visitor", return_type="T"}}, signature="(dir: string, visitor: Visitor, ctx?: T): T"}, {description=" Collect file paths matching a Lua pattern.\n Recursively walks directory tree and returns matching file paths.", is_local=true, line=67, name="collect", params={{description="The directory to search", name="dir", param_type="string"}, {description="Lua pattern to match against file basenames", name="pattern", param_type="string"}}, returns={{description="List of full paths to matching files", return_type="{string}"}}, signature="(dir: string, pattern: string): {string}"}, {description=" Recursively collect all files with their Unix permissions.\n Returns a map of relative paths to file information.", is_local=true, line=84, name="collect_all", params={{description="The directory to walk", name="dir", param_type="string"}, {description="Internal: relative path prefix (used during recursion)", name="base", param_type="string"}, {description="Internal: accumulator map (used during recursion)", name="files", param_type="{string:FileInfo}"}}, returns={{description="Map of relative paths to file information", return_type="{string:FileInfo}"}}, signature=