: Returns a Writer for creating a new archive (overwrites existing)\n - \"a\": Returns an Appender for adding files to an existing archive", is_local=true, line=98, name="open", params={{description="File path or file descriptor", name="path", param_type="string|number"}, {description="Mode: \"r\" (read), \"w\" (write), or \"a\" (append). Default is \"r\".", name="mode", param_type="string?"}, {description="Compression level and size limits", name="options", param_type="OpenOptions?"}}, returns={{description="The archive handle (Reader, Writer, or Appender based on mode), or nil on error", return_type="any"}, {description="Error message if opening failed", return_type="string?"}}, signature="(path: string | number, mode?: string, options?: OpenOptions): any, string"}, {description=" Open a ZIP archive from in-memory data for reading.", is_local=true, line=122, name="from", params={{description="The ZIP archive data", name="data", param_type="string"}, {description="Size limits", name="options", param_type="OpenOptions?"}}, returns={{description="The archive reader, or nil on error", return_type="Reader?"}, {description="Error message if opening failed", return_type="string?"}}, signature="(data: string, options?: OpenOptions): Reader, string"}}, module_doc=" ZIP archive reading and writing utilities.\n Wraps cosmo.zip with a convenient Teal-typed interface for creating, reading, and modifying ZIP archives.", records={{description=" Options for opening a ZIP archive.", fields={{"level", "number", " Compression level 0-9 (0=none, 9=maximum). Used for \"w\" and \"a\" modes."}, {"max_file_size", "number", " Maximum file size limit in bytes."}}, line=6, name="OpenOptions"}, {description=" Options for adding a file to a ZIP archive.", fields={{"method", "\"store\" (no compression) or \"deflate\" (compressed).", ""}, {"method", "string", " Compression method: \"store\" (no compression) or \"deflate\" (compressed)."}, {"mtime", "number", " Modification time as Unix timestamp."}, {"mode", "number", " Unix file mode/permissions (default 0644)."}}, line=14, name="AddOptions"}, {description=" File metadata within a ZIP archive.", fields={{"size", "number", " Uncompressed file size in bytes."}, {"compressed_size", "number", " Compressed file size in bytes."}, {"crc32", "number", " CRC32 checksum of uncompressed data."}, {"mtime", "number", " Modification time as Unix timestamp."}, {"method", "number", " Compression method (0=stored, 8=deflated)."}, {"mode", "number", " Unix file mode/permissions."}}, line=24, name="Stat"}, {description=" Reader for extracting files from a ZIP archive.", fields={{"list", "function(self: Reader): {string}", " Lists all files in the ZIP archive."}, {"stat", "function(self: Reader, name: string): Stat", " Gets metadata for a specific file in the archive."}, {"read", "function(self: Reader, name: string): string, string", " Reads the contents of a file from the archive."}, {"close", "function(self: Reader)", " Closes the ZIP reader and releases resources."}}, line=40, name="Reader"}, {description=" Writer for creating new ZIP archives.", fields={{"add", "function(self: Writer, name: string, content: string, options?: AddOptions): boolean, string", " Adds a file to the ZIP archive."}, {"close", "function(self: Writer)", " Closes the ZIP archive and writes the central directory."}}, line=61, name="Writer"}, {description=" Appender for adding files to an existing ZIP archive.", fields={{"add", "function(self: Appender, name: string, content: string, options?: AddOptions): boolean, string", " Adds a file to the ZIP archive."}, {"close", "function(self: Appender)", " Closes the ZIP archive and writes the updated central directory."}}, line=75, name="Appender"}, {fields={{"open", "function(path: string | number, mode?: string, options?: OpenOptions): any, string", ""}, {"from", "function(data: string, options?: OpenOptions): Reader, string", ""}}, line=141, name="ZipModule"}}}, ["cosmo.argon2"]={examples={}, file="lib/types/cosmo/argon2.d.tl", functions={{description=" Hashes password.\n This is consistent with the README of the reference implementation:\n >: assert(argon2.hash_encoded(\"password\", \"somesalt\", {\n variant = argon2.variants.argon2_i,\n hash_len = 24,\n t_cost = 2,\n }))\n `salt` is a nonce value used to hash the string.\n `config.m_cost` is the memory hardness in kibibytes, which defaults\n to 4096 (4 mibibytes). It's recommended that this be tuned upwards.\n `config.t_cost` is the number of iterations, which defaults to 3.\n `config.parallelism` is the parallelism factor, which defaults to 1.\n `config.hash_len` is the number of desired bytes in hash output,\n which defaults to 32.\n `config.variant` may be:\n - `argon2.variants.argon2_id` blend of other two methods [default]\n - `argon2.variants.argon2_i` maximize resistance to side-channel attacks\n - `argon2.variants.argon2_d` maximize resistance to gpu cracking attacks", is_local=false, line=0, name="hash_encoded", params={{name="pass", param_type="string"}, {name="salt", param_type="string"}, {name="config", param_type="Config"}}, returns={{return_type="string"}}, signature="(pass: string, salt: string, config: Config): string"}, {description=" Verifies password, e.g.\n >: argon2.verify(\n \"p=4$c29tZXNhbHQ$RdescudvJCsgt3ub+b+dWRWJTmaaJObG\",\n true", is_local=false, line=0, name="verify", params={{name="encoded", param_type="string"}, {name="pass", param_type="string"}}, returns={{return_type="boolean"}}, signature="(encoded: string, pass: string): boolean"}}, module_doc="Type declarations for the `argon2` module.", records={}}, ["cosmo.finger"]={examples={}, file="lib/types/cosmo/finger.d.tl", functions={{description=" Fingerprints IP+TCP SYN packet.\n This returns a hash-like magic number that reflects the SYN packet structure,\n e.g. ordering of options, maximum segment size, etc. We make no guarantees this\n hashing algorithm won't change as we learn more about the optimal way to\n - fingerprint, so be sure to save your syn packets too if you're using this\n feature, in case they need to be rehashed in the future.\n This function is nil/error propagating.", is_local=false, line=0, name="FingerSyn", params={{name="syn_packet_bytes", param_type="string"}}, returns={{return_type="number"}}, signature="(syn_packet_bytes: string): number"}, {description=" Fingerprints IP+TCP SYN packet.\n If synfinger is a known hard-coded magic number, then one of the following\n strings may be returned:\n - `\"LINUX\"`\n - `\"WINDOWS\"`\n - `\"XNU\"`\n - `\"NETBSD\"`\n - `\"FREEBSD\"`\n - `\"OPENBSD\"`\n If this function returns `nil`, then one thing you can do to help is file an\n issue and share with us your SYN packet specimens. The way we prefer to receive\n them is in `EncodeLua(syn_packet_bytes)` format along with details on the\n operating system which you must know.", is_local=false, line=0, name="GetSynFingerOs", params={{name="synfinger", param_type="number"}}, returns={{return_type="\"LINUX\""}}, signature="(synfinger: number): \"LINUX\""}, {description=" Describes IP+TCP SYN packet.\n The layout looks as follows:\n - `TTL:OPTIONS:WSIZE:MSS`\n The `TTL`, `WSIZE`, and `MSS` fields are unsigned decimal fields.\n The `OPTIONS` field communicates the ordering of the commonly used subset of\n tcp options. The following character mappings are defined. TCP options not on\n this list will be ignored.\n - `E`: End of Option list\n - `N`: No-Operation\n - `M`: Maximum Segment Size\n - `K`: Window Scale\n - `O`: SACK Permitted\n - `A`: SACK\n - `e`: Echo (obsolete)\n - `r`: Echo reply (obsolete)\n - `T`: Timestamps\n This function is nil/error propagating.", is_local=false, line=0, name="DescribeSyn", params={{name="syn_packet_bytes", param_type="string"}}, returns={{return_type="string"}}, signature="(syn_packet_bytes: string): string"}}, module_doc="Type declarations for the `finger` module.", records={}}, ["cosmo.getopt"]={examples={}, file="lib/types/cosmo/getopt.d.tl", functions={{description=" Create a new getopt parser for iterating through command-line options.\n The optstring uses standard getopt format:\n - A letter means that option takes no argument\n - A letter followed by : means it requires an argument\n - A letter followed by :: means it takes an optional argument\n The longopts table contains entries like {\"name\", \"has_arg\", \"short\"}:\n - name: the long option name (e.g., \"help\" for --help)\n - has_arg: \"none\", \"required\", or \"optional\"\n - short: the equivalent short option character (e.g., \"h\")\n Example - Basic usage:\n     local parser = getopt.new(arg, \"hvo:\", {\n       {\"help\",    \"none\",     \"h\"},\n       {\"verbose\", \"none\",     \"v\"},\n       {\"output\",  \"required\", \"o\"},\n     })\n     while true do\n       local opt, arg = parser:next()\n       if not opt then break end\n       if opt == \"h\" or opt == \"help\" then\n         print(\"Usage: ...\")\n       elseif opt == \"v\" or opt == \"verbose\" then\n         verbose = true\n       elseif opt == \"o\" or opt == \"output\" then\n         output = arg\n       end\n     end\n     local remaining = parser:remaining()  -- non-option args\n     local unknown = parser:unknown()      -- unrecognized options\n Example - Handling repeated options:\n     local parser = getopt.new(arg, \"e:\", {})\n     local excludes = {}\n     while true do\n       local opt, arg = parser:next()\n       if not opt then break end\n       if opt == \"e\" then\n         table.insert(excludes, arg)\n       end\n     end\n     -- Now excludes contains all -e values: {\"foo\", \"bar\", \"spam\"}", is_local=false, line=0, name="new", params={{name="args", param_type="{string}"}, {name="optstring", param_type="string"}, {name="longopts", param_type="{table}"}}, returns={{return_type="parser"}}, signature="(args: {string}, optstring: string, longopts?: {table}): parser"}}, module_doc="Type declarations for the `getopt` module.", records={{fields={{"next", "function(self: parser): string | nil, string | nil", " Get the next option from the parser.\n Returns the next option character or long name, along with its argument\n if the option takes one. Returns nil when no more options remain.\n If the option is unknown, returns \"?\" as the option name and the unknown\n option string as the argument."}, {"remaining", "function(self: parser): {string}", " Get remaining non-option arguments after all options have been parsed."}, {"unknown", "function(self: parser): {string}", " Get any unknown options that were encountered during parsing."}}, line=0, name="parser"}}}, ["cosmo.goodsocket"]={examples={}, file="lib/types/cosmo/goodsocket.d.tl", functions={{description=" Creates a socket with modern TCP optimizations enabled.\n This function wraps GoodSocket() which automatically enables performance\n features like TCP Fast Open, Quick ACK, and other optimizations based on\n whether you're creating a client or server socket.\n Example:\n local gs = require(\"cosmo.goodsocket\")\n local unix = require(\"cosmo.unix\")\n -- Create a TCP client socket\n local fd = assert(gs.socket(gs.AF_INET, gs.SOCK_STREAM, gs.IPPROTO_TCP, false))\n unix.close(fd)\n -- Create a TCP server socket with 30 second timeout\n local fd = assert(gs.socket(gs.AF_INET, gs.SOCK_STREAM, gs.IPPROTO_TCP, true, 30))\n unix.close(fd)", is_local=false, line=0, name="socket", params={{name="family", param_type="number"}, {name="type", param_type="number"}, {name="protocol", param_type="number"}, {name="isserver", param_type="boolean"}, {name="timeout", param_type="number"}}, returns={{return_type="number"}}, signature="(family: number, type: number, protocol: number, isserver: boolean, timeout?: number): number"}}, module_doc="Type declarations for the `goodsocket` module.", records={{description="Constants defined in the goodsocket module.", fields={{"AF_INET", "number", ""}, {"AF_INET6", "number", ""}, {"AF_UNIX", "number", ""}, {"AF_UNSPEC", "number", ""}, {"SOCK_STREAM", "number", ""}, {"SOCK_DGRAM", "number", ""}, {"SOCK_RAW", "number", ""}, {"SOCK_RDM", "number", ""}, {"SOCK_SEQPACKET", "number", ""}, {"IPPROTO_IP", "number", ""}, {"IPPROTO_TCP", "number", ""}, {"IPPROTO_UDP", "number", ""}, {"IPPROTO_ICMP", "number", ""}, {"IPPROTO_IPV6", "number", ""}, {"IPPROTO_ICMPV6", "number", ""}, {"IPPROTO_RAW", "number", ""}}, line=0, name="goodsocket Constants"}}}, ["cosmo.lsqlite3"]={examples={}, file="lib/types/cosmo/lsqlite3.d.tl", functions={{description=" Opens (or creates if it does not exist) an SQLite database with name filename\n and returns its handle as userdata (the returned object should be used for all\n further method calls in connection with this specific database, see Database\n methods). Example:\n myDB = lsqlite3.open('MyDatabase.sqlite3')  -- open\n -- do some database calls...\n myDB:close()  -- close\n In case of an error, the function returns `nil`, an error code and an error message.\n Since `0.9.4`, there is a second optional `flags` argument to `lsqlite3.open`.\n See https://www.sqlite.org/c3ref/open.html for an explanation of these flags and options.\n local db = lsqlite3.open('foo.db', lsqlite3.OPEN_READWRITE + lsqlite3.OPEN_CREATE + lsqlite3.OPEN_SHAREDCACHE)", is_local=false, line=0, name="open", params={{name="filename", param_type="string"}, {name="flags", param_type="number"}}, returns={{return_type="Database"}}, signature="(filename: string, flags?: number): Database"}, {description=" Opens an SQLite database in memory and returns its handle as userdata. In case\n of an error, the function returns `nil`, an error code and an error message.\n (In-memory databases are volatile as they are never stored on disk.)", is_local=false, line=0, name="open_memory", params={}, returns={{return_type="Database"}}, signature="(): Database"}, {is_local=false, line=0, name="lversion", params={}, returns={{return_type="string"}}, signature="(): string"}, {is_local=false, line=0, name="version", params={}, returns={{re