tring | nil", " Compiles SQL statement into prepared statement for reuse\n Returns Statement on success, or (nil, errcode, errmsg) on failure"}, {"nrows", "function(Database, sql: string): function(): {string:any}", " Creates iterator yielding rows as tables with named fields (column_name: value)\n Each iteration returns one row as associative table"}, {"rows", "function(Database, sql: string): function(): {any}", " Creates iterator yielding rows as indexed tables (1: value1, 2: value2, ...)\n Each iteration returns one row as array with numeric indices"}, {"urows", "function(Database, sql: string): function(): any...", " Creates iterator yielding column values directly (value1, value2, ...)\n Each iteration returns unpacked values for one row"}, {"last_insert_rowid", "function(Database): number", " Returns rowid of most recent INSERT operation\n Returns 0 if no inserts have occurred"}, {"changes", "function(Database): number", " Returns count of rows modified by most recent INSERT, UPDATE, or DELETE\n Excludes trigger-caused changes"}, {"total_changes", "function(Database): number", " Returns cumulative count of all rows modified since database opened\n Includes changes in triggers"}, {"errcode", "function(Database): number", " Retrieves numerical error code from most recent failed operation"}, {"errmsg", "function(Database): string", " Retrieves human-readable error message for most recent failed call"}}, line=0, name="Database"}, {description="Constants defined in the lsqlite3 module.", fields={{"OK", "number", ""}, {"ERROR", "number", ""}, {"INTERNAL", "number", ""}, {"PERM", "number", ""}, {"ABORT", "number", ""}, {"BUSY", "number", ""}, {"LOCKED", "number", ""}, {"NOMEM", "number", ""}, {"READONLY", "number", ""}, {"INTERRUPT", "number", ""}, {"IOERR", "number", ""}, {"CORRUPT", "number", ""}, {"NOTFOUND", "number", ""}, {"FULL", "number", ""}, {"CANTOPEN", "number", ""}, {"PROTOCOL", "number", ""}, {"EMPTY", "number", ""}, {"SCHEMA", "number", ""}, {"TOOBIG",