 speaking zombies) and if so harvest them immediately.\n Returns the process id of the child that terminated. In other\n cases, the returned `pid` is nil and `errno` is non-nil.\n The returned `wstatus` contains information about the process\n exit status. It's a complicated integer and there's functions\n that can help interpret it. For example:\n -- wait for zombies\n -- traditional technique for SIGCHLD handlers\n while true do\n pid, status = unix.wait(-1, unix.WNOHANG)\n if pid then\n if unix.WIFEXITED(status) then\n print('child', pid, 'exited with',\n unix.WEXITSTATUS(status))\n elseif unix.WIFSIGNALED(status) then\n print('child', pid, 'crashed with',\n unix.strsignal(unix.WTERMSIG(status)))\n end\n elseif status:errno() == unix.ECHILD then\n Log(kLogDebug, 'no more zombies')\n break\n else\n Log(kLogWarn, tostring(err))\n break\n end\n end", is_local=false, line=0, name="wait", params={{name="pid", param_type="number"}, {name="options", param_type="number"}}, returns={{return_type="number"}, {return_type="number"}, {return_type="Rusage"}}, signature="(pid?: number, options?: number): number, number, Rusage"}, {description=" Returns `true` if process exited cleanly.", is_local=false, line=0, name="WIFEXITED", params={{name="wstatus", param_type="number"}}, returns={{return_type="boolean"}}, signature="(wstatus: number): boolean"}, {description=" Returns code passed to exit() assuming `WIFEXITED(wstatus)` is true.", is_local=false, line=0, name="WEXITSTATUS", params={{name="wstatus", param_type="number"}}, returns={{return_type="number"}}, signature="(wstatus: number): number"}, {description=" Returns `true` if process terminated due to a signal.", is_local=false, line=0, name="WIFSIGNALED", params={{name="wstatus", param_type="number"}}, returns={{return_type="boolean"}}, signature="(wstatus: number): boolean"}, {description=" Returns signal that caused process to terminate assuming\n `WIFSIGNALED(wstatus)` is `true`.", is_local=false, line=0, name="WTERMSIG